from __future__ import annotations

from itertools import groupby


def encode(s: str) -> str:
    """Encode runs of repeated characters as the character followed by its length.

    A run of length one omits the count, so ``encode('aaabcc') == 'a3bc2'``.
    """
    return ''.join(
        f'{char}{len(run) if len(run) > 1 else ""}'
        for char, run in ((char, list(chars)) for char, chars in groupby(s))
    )


def decode(s: str) -> str:
    """Decode a string produced by :func:`encode`, including multi-digit runs."""
    result: list[str] = []
    i = 0
    while i < len(s):
        char = s[i]
        if char.isdigit():
            raise ValueError(f'Expected a character at position {i}, got digit {char!r}')
        i += 1

        start = i
        while i < len(s) and s[i].isdigit():
            i += 1

        count = int(s[start:i]) if i > start else 1
        result.append(char * count)

    return ''.join(result)


